-- Add Zoom/provider-neutral meeting integration support.
CREATE TYPE "MeetingProvider" AS ENUM ('ZOOM', 'GOOGLE_MEET', 'MICROSOFT_TEAMS', 'NATIVE_LIVEKIT', 'EXTERNAL_LINK');
CREATE TYPE "IntegrationProvider" AS ENUM ('ZOOM', 'GOOGLE', 'MICROSOFT');
CREATE TYPE "IntegrationStatus" AS ENUM ('CONNECTED', 'EXPIRED', 'REVOKED', 'ERROR');
CREATE TYPE "ProviderWebhookEventStatus" AS ENUM ('RECEIVED', 'PROCESSED', 'IGNORED', 'FAILED');
CREATE TYPE "MeetingProviderArtifactStatus" AS ENUM ('DISCOVERED', 'IMPORTING', 'IMPORTED', 'FAILED', 'SKIPPED');
ALTER TABLE "MeetingRoom" ADD COLUMN "provider" "MeetingProvider" NOT NULL DEFAULT 'NATIVE_LIVEKIT', ADD COLUMN "providerMeetingId" TEXT, ADD COLUMN "providerHostId" TEXT, ADD COLUMN "providerAccountId" TEXT, ADD COLUMN "providerJoinUrl" TEXT, ADD COLUMN "providerStartUrlEncrypted" TEXT, ADD COLUMN "providerStatus" TEXT, ADD COLUMN "providerMetadata" JSONB, ADD COLUMN "providerSyncedAt" TIMESTAMP(3);
ALTER TABLE "MeetingRecording" ADD COLUMN "providerArtifactId" TEXT, ADD COLUMN "providerMeetingId" TEXT, ADD COLUMN "providerRecordingType" TEXT, ADD COLUMN "providerFileType" TEXT, ADD COLUMN "providerDownloadState" TEXT, ADD COLUMN "providerSource" "MeetingProvider";
CREATE TABLE "WorkspaceMeetingIntegration" ("id" TEXT NOT NULL, "workspaceId" TEXT NOT NULL, "provider" "IntegrationProvider" NOT NULL, "status" "IntegrationStatus" NOT NULL DEFAULT 'CONNECTED', "providerAccountId" TEXT, "providerAccountName" TEXT, "accessTokenEncrypted" TEXT NOT NULL, "refreshTokenEncrypted" TEXT, "accessTokenExpiresAt" TIMESTAMP(3), "scopes" JSONB, "connectedById" TEXT NOT NULL, "connectedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "disconnectedAt" TIMESTAMP(3), "lastRefreshedAt" TIMESTAMP(3), "safeFailureMessage" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WorkspaceMeetingIntegration_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProviderWebhookEvent" ("id" TEXT NOT NULL, "provider" "IntegrationProvider" NOT NULL, "providerEventId" TEXT NOT NULL, "eventType" TEXT NOT NULL, "providerMeetingId" TEXT, "workspaceId" TEXT, "receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "processedAt" TIMESTAMP(3), "status" "ProviderWebhookEventStatus" NOT NULL DEFAULT 'RECEIVED', "safeFailureMessage" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ProviderWebhookEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MeetingProviderArtifact" ("id" TEXT NOT NULL, "workspaceId" TEXT NOT NULL, "meetingRoomId" TEXT NOT NULL, "recordingId" TEXT, "provider" "MeetingProvider" NOT NULL, "providerArtifactId" TEXT NOT NULL, "providerMeetingId" TEXT NOT NULL, "recordingType" TEXT, "fileType" TEXT, "mimeType" TEXT, "fileSizeBytes" BIGINT, "startedAt" TIMESTAMP(3), "endedAt" TIMESTAMP(3), "status" "MeetingProviderArtifactStatus" NOT NULL DEFAULT 'DISCOVERED', "importedStorageKey" TEXT, "providerDownloadState" TEXT, "transcriptArtifactId" TEXT, "safeMetadata" JSONB, "safeFailureMessage" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "MeetingProviderArtifact_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WorkspaceMeetingIntegration_workspaceId_provider_key" ON "WorkspaceMeetingIntegration"("workspaceId", "provider");
CREATE INDEX "WorkspaceMeetingIntegration_workspaceId_provider_status_idx" ON "WorkspaceMeetingIntegration"("workspaceId", "provider", "status");
CREATE INDEX "WorkspaceMeetingIntegration_provider_providerAccountId_idx" ON "WorkspaceMeetingIntegration"("provider", "providerAccountId");
CREATE UNIQUE INDEX "ProviderWebhookEvent_provider_providerEventId_key" ON "ProviderWebhookEvent"("provider", "providerEventId");
CREATE INDEX "ProviderWebhookEvent_provider_eventType_receivedAt_idx" ON "ProviderWebhookEvent"("provider", "eventType", "receivedAt");
CREATE INDEX "ProviderWebhookEvent_provider_providerMeetingId_idx" ON "ProviderWebhookEvent"("provider", "providerMeetingId");
CREATE INDEX "ProviderWebhookEvent_workspaceId_idx" ON "ProviderWebhookEvent"("workspaceId");
CREATE UNIQUE INDEX "MeetingProviderArtifact_workspaceId_provider_providerArtifactId_key" ON "MeetingProviderArtifact"("workspaceId", "provider", "providerArtifactId");
CREATE INDEX "MeetingProviderArtifact_workspaceId_meetingRoomId_status_idx" ON "MeetingProviderArtifact"("workspaceId", "meetingRoomId", "status");
CREATE INDEX "MeetingProviderArtifact_provider_providerMeetingId_idx" ON "MeetingProviderArtifact"("provider", "providerMeetingId");
CREATE INDEX "MeetingRoom_workspaceId_provider_providerMeetingId_idx" ON "MeetingRoom"("workspaceId", "provider", "providerMeetingId");
CREATE INDEX "MeetingRoom_workspaceId_providerAccountId_idx" ON "MeetingRoom"("workspaceId", "providerAccountId");
CREATE UNIQUE INDEX "MeetingRecording_workspaceId_provider_providerArtifactId_key" ON "MeetingRecording"("workspaceId", "provider", "providerArtifactId");
CREATE INDEX "MeetingRecording_workspaceId_providerSource_providerMeetingId_idx" ON "MeetingRecording"("workspaceId", "providerSource", "providerMeetingId");
ALTER TABLE "WorkspaceMeetingIntegration" ADD CONSTRAINT "WorkspaceMeetingIntegration_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "WorkspaceMeetingIntegration" ADD CONSTRAINT "WorkspaceMeetingIntegration_connectedById_fkey" FOREIGN KEY ("connectedById") REFERENCES "UserProfile"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ProviderWebhookEvent" ADD CONSTRAINT "ProviderWebhookEvent_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "MeetingProviderArtifact" ADD CONSTRAINT "MeetingProviderArtifact_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MeetingProviderArtifact" ADD CONSTRAINT "MeetingProviderArtifact_meetingRoomId_fkey" FOREIGN KEY ("meetingRoomId") REFERENCES "MeetingRoom"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "MeetingProviderArtifact" ADD CONSTRAINT "MeetingProviderArtifact_recordingId_fkey" FOREIGN KEY ("recordingId") REFERENCES "MeetingRecording"("id") ON DELETE SET NULL ON UPDATE CASCADE;
